<template><Head title="Invoices"/><PortalLayout area="Customer Portal"><template #navigation><CustomerNavigation active="invoices"/></template><div class="mb-6 flex flex-wrap items-end justify-between gap-4"><div><h1 class="text-3xl font-bold">Invoices</h1><p class="mt-2 text-slate-600">Review invoices, payment history and outstanding balances.</p></div><Link :href="route('portal.payments.create')" class="form-button">Submit manual payment</Link></div><p v-if="$page.props.flash.error" class="mb-5 rounded-xl bg-red-50 p-4 font-semibold text-red-800">{{ $page.props.flash.error }}</p><p v-if="$page.props.flash.success" class="success-message mb-5">{{ $page.props.flash.success }}</p><div class="overflow-x-auto rounded-2xl bg-white p-5 shadow-sm ring-1 ring-slate-200"><table class="min-w-full text-left text-sm"><thead class="text-slate-500"><tr><th class="py-3">Invoice</th><th>Account</th><th>Issued</th><th>Due</th><th>Total</th><th>Balance</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="invoice in invoices" :key="invoice.uuid" class="border-t"><td class="py-4"><Link :href="route('portal.invoices.show',invoice.uuid)" class="font-bold text-[#0B3D6E] hover:text-[#0797A5]">{{ invoice.number }}</Link></td><td>{{ invoice.customer }}</td><td>{{ invoice.issue_date }}</td><td>{{ invoice.due_date }}</td><td>{{ money(invoice.total,invoice.currency) }}</td><td class="font-semibold">{{ money(invoice.balance,invoice.currency) }}</td><td class="uppercase">{{ invoice.status }}</td><td class="text-right"><Link :href="route('portal.invoices.show',invoice.uuid)" class="font-bold text-cyan-700">{{ Number(invoice.balance)>0 ? 'View / Pay' : 'View' }}</Link></td></tr></tbody></table><p v-if="!invoices.length" class="py-8 text-center text-slate-500">No invoices are available.</p></div></PortalLayout></template>
